"use strict";(globalThis.webpackChunklearngenomics_dev||=[]).push([[6354],{9020(e,t,n){n.r(t),n.d(t,{assets:()=>p,contentTitle:()=>g,default:()=>f,frontMatter:()=>m,metadata:()=>l,toc:()=>u});var s=n.cw((e,t)=>{const s=n.p+"assets/images/7.3-methylated-cpg-dark-f06f1144972189757cc1b858f60581fa.svg";n.d(t,["A",0,s])}),a=n.cw((e,t)=>{const s=n.p+"assets/images/7.4-methylation-copying-dark-9f014f2a358f08bd6510c8f8004c920d.svg";n.d(t,["A",0,s])}),i=n.cw((e,t)=>{const s=n.p+"assets/images/7.5-histone-marks-dark-87f1997d01c3cd8c6bd7ba51c6b0ed02.svg";n.d(t,["A",0,s])}),o=n.cw((e,t)=>{const s=n.p+"assets/images/7.3-methylated-cpg-be5032de2eba8fd54a6d4f3d61011f6b.svg";n.d(t,["A",0,s])}),r=n.cw((e,t)=>{const s=n.p+"assets/images/7.4-methylation-copying-f84d81d1ca097cc154a1d8c277a89c55.svg";n.d(t,["A",0,s])}),h=n.cw((e,t)=>{const s=n.p+"assets/images/7.5-histone-marks-3f2f6e6e2d1fea7eb827ccb78474ede6.svg";n.d(t,["A",0,s])});const l=JSON.parse('{"id":"advanced-topics/epigenetic-modifications","title":"Epigenetic Modifications","description":"Epigenetic marks: DNA methylation and histone modifications, how they hold gene activity in place, how they are measured, and their role in cancer.","source":"@site/docs/07-advanced-topics/epigenetic-modifications.md","sourceDirName":"07-advanced-topics","slug":"/advanced-topics/epigenetic-modifications","permalink":"/docs/advanced-topics/epigenetic-modifications","draft":false,"unlisted":false,"editUrl":"https://github.com/stjude/learngenomics.dev/tree/main/docs/07-advanced-topics/epigenetic-modifications.md","tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"title":"Epigenetic Modifications","description":"Epigenetic marks: DNA methylation and histone modifications, how they hold gene activity in place, how they are measured, and their role in cancer.","track":"Advanced Topics","sidebar_position":2},"sidebar":"tutorialSidebar","previous":{"title":"Alternative Splicing","permalink":"/docs/advanced-topics/alternative-splicing"},"next":{"title":"Noncoding RNAs","permalink":"/docs/advanced-topics/non-coding-rnas"}}');var d=n(4848),c=n(8453);const m={title:"Epigenetic Modifications",description:"Epigenetic marks: DNA methylation and histone modifications, how they hold gene activity in place, how they are measured, and their role in cancer.",track:"Advanced Topics",sidebar_position:2},g=void 0,p={},u=[{value:"DNA Methylation",id:"dna-methylation",level:2},{value:"Copying the Marks",id:"copying-the-marks",level:3},{value:"Histone Modifications",id:"histone-modifications",level:2},{value:"Measuring the Marks",id:"measuring-the-marks",level:2},{value:"Epigenetics in Cancer",id:"epigenetics-in-cancer",level:2},{value:"Too Little and Too Much Methylation",id:"too-little-and-too-much-methylation",level:3},{value:"Mutations in the Machinery",id:"mutations-in-the-machinery",level:3}];function y(e){const t={a:"a",figcaption:"figcaption",figure:"figure",h2:"h2",h3:"h3",img:"img",li:"li",p:"p",span:"span",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,c.R)(),...e.components};return(0,d.jsxs)(d.Fragment,{children:[(0,d.jsxs)(t.p,{children:["Nearly every cell in your body carries the same genome, yet a neuron and a white blood\ncell look and behave nothing alike. What differs is which genes each cell uses. Part of\nwhat holds those choices in place is a layer of chemical marks on the DNA and on the\nhistones it wraps around. Epigenetics is the study of changes in gene activity that can\nbe passed on when a cell divides but can't be explained by changes in the DNA sequence\n(",(0,d.jsx)(t.a,{href:"https://doi.org/10.1101/gad.947102",children:"Bird, 2002"}),"). This guide covers the two\nbest-studied kinds of marks, how they're measured and what happens to them in cancer."]}),"\n",(0,d.jsx)(t.h2,{id:"dna-methylation",children:"DNA Methylation"}),"\n",(0,d.jsxs)(t.p,{children:["The most common mark on human DNA is a ",(0,d.jsx)(t.strong,{children:"methyl group"}),", one carbon atom with three\nhydrogens (CH3), attached to carbon 5 of a cytosine. The result is called\n",(0,d.jsx)(t.strong,{children:"5-methylcytosine"})," (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/npp.2012.112",children:"Moore et al., 2013"}),"). In\nmost human cells it's found almost only at ",(0,d.jsx)(t.strong,{children:"CpG sites"}),', where a C is followed by a G\non the same strand; the "p" stands for the phosphate that links them. CG read 5\u2032 to 3\u2032\nis its own ',(0,d.jsx)(t.a,{href:"/docs/advanced-topics/dna-structure#reading-the-other-strand",children:"reverse complement"}),", so the other\nstrand has a CpG at the same spot, and the two cytosines sit diagonally across from each\nother (",(0,d.jsx)(t.a,{href:"#figure-7-3",children:"Figure 7.3"}),"). In human body cells, 70% to 80% of all CpG sites are\nmethylated, as Bird's review notes."]}),"\n",(0,d.jsxs)(t.figure,{className:"lg-figure lg-figure--tall lg-figure--themed",id:"figure-7-3",children:[(0,d.jsx)(t.img,{alt:"Two stacked DNA base pairs drawn atom by atom, on two strands that run in opposite directions. The left strand reads from its 5\u2032 end at the top to its 3\u2032 end at the bottom: 5-methylcytosine above guanine. The right strand runs the other way: guanine on top paired with the upper 5-methylcytosine, and 5-methylcytosine at the bottom paired with the lower guanine. Each 5-methylcytosine carries a CH3 group, highlighted as the methyl group, on carbon 5 of the cytosine ring, on the side away from the hydrogen bonds. Each pair is held together by three dotted hydrogen bonds. Phosphates and deoxyribose sugars form the backbone of each strand.",src:o().A+"",width:"415",height:"520"}),(0,d.jsx)(t.img,{className:"lg-figure__dark",src:s().A,alt:"Two stacked DNA base pairs drawn atom by atom, on two strands that run in opposite directions. The left strand reads from its 5\u2032 end at the top to its 3\u2032 end at the bottom: 5-methylcytosine above guanine. The right strand runs the other way: guanine on top paired with the upper 5-methylcytosine, and 5-methylcytosine at the bottom paired with the lower guanine. Each 5-methylcytosine carries a CH3 group, highlighted as the methyl group, on carbon 5 of the cytosine ring, on the side away from the hydrogen bonds. Each pair is held together by three dotted hydrogen bonds. Phosphates and deoxyribose sugars form the backbone of each strand.",width:"415",height:"519.75",loading:"lazy",decoding:"async"}),(0,d.jsxs)(t.figcaption,{children:[(0,d.jsx)(t.span,{className:"lg-figure__number",children:"Figure 7.3"})," A methylated CpG site. Both strands read 5\u2032-CG-3\u2032, so their two cytosines sit diagonally across from each other, and each carries a methyl group on carbon 5. The methyl group points away from the hydrogen bonds, so each 5-methylcytosine pairs with guanine through the same three bonds as an ordinary C\u2060\u2013\u2060G pair."]})]}),"\n",(0,d.jsxs)(t.p,{children:["CpG sites are scarce across most of the genome but cluster in stretches about 1,000\nbases long called ",(0,d.jsx)(t.strong,{children:"CpG islands"}),", which normally stay unmethylated (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1101/gad.2037511",children:"Deaton and Bird,\n2011"}),"). About 70% of gene\n",(0,d.jsx)(t.a,{href:"/docs/biological-foundations/transcription#genomic-regions-and-transcription",children:"promoters"}),"\nsit in a CpG island (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1073/pnas.0510310103",children:"Saxonov et al., 2006"}),").\nDense methylation of a promoter's island helps lock the gene in a silent state. Bird's\nreview names two places where cells do this on purpose during development: the inactive\nX chromosome in females, and imprinted genes, where only the copy inherited from one\nparent is used."]}),"\n",(0,d.jsx)(t.h3,{id:"copying-the-marks",children:"Copying the Marks"}),"\n",(0,d.jsxs)(t.p,{children:["When a cell divides, its methylation is copied along with its DNA, so the marks outlast\nthe cell that made them (",(0,d.jsx)(t.a,{href:"#figure-7-4",children:"Figure 7.4"}),"). A new strand is built from plain\ncytosines, so right after copying, each CpG that was methylated on both strands now\ncarries a methyl group on the old strand only, a state called ",(0,d.jsx)(t.strong,{children:"hemimethylated"}),". A\nprotein called UHRF1 binds these half-marked sites (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1126/science.1147939",children:"Bostick et al.,\n2007"}),"), and the enzyme ",(0,d.jsx)(t.strong,{children:"DNMT1"})," adds a methyl\ngroup to the new strand's C wherever the old strand has one. The copying isn't perfect,\nso now and then a site loses its mark."]}),"\n",(0,d.jsxs)(t.figure,{className:"lg-figure lg-figure--themed",id:"figure-7-4",children:[(0,d.jsx)(t.img,{alt:"Three rows, each showing DNA as pairs of horizontal strands with cytosines at three CpG sites drawn as small circles on stems. Row 1, both strands carry the marks: one duplex of two old strands, with every circle filled to show a methylated cytosine. Row 2, copying makes two half-marked duplexes: each duplex has one old strand with filled circles and one new strand with open circles, unmethylated. Row 3, DNMT1 marks the new strands to match: the same two duplexes, now with every circle filled. A key identifies filled circles as methylated cytosine, open circles as unmethylated cytosine, and the two strand shades as old strand and new strand.",src:r().A+"",width:"392",height:"327"}),(0,d.jsx)(t.img,{className:"lg-figure__dark",src:a().A,alt:"Three rows, each showing DNA as pairs of horizontal strands with cytosines at three CpG sites drawn as small circles on stems. Row 1, both strands carry the marks: one duplex of two old strands, with every circle filled to show a methylated cytosine. Row 2, copying makes two half-marked duplexes: each duplex has one old strand with filled circles and one new strand with open circles, unmethylated. Row 3, DNMT1 marks the new strands to match: the same two duplexes, now with every circle filled. A key identifies filled circles as methylated cytosine, open circles as unmethylated cytosine, and the two strand shades as old strand and new strand.",width:"392",height:"327",loading:"lazy",decoding:"async"}),(0,d.jsxs)(t.figcaption,{children:[(0,d.jsx)(t.span,{className:"lg-figure__number",children:"Figure 7.4"})," How methylation is copied when a cell divides. Copying pairs each old strand with a new strand that has no methyl groups, leaving two hemimethylated duplexes. DNMT1 then methylates each new strand opposite the old strand's marks, so both copies match the original."]})]}),"\n",(0,d.jsxs)(t.p,{children:["Other enzymes change the pattern. DNMT3A and DNMT3B add methyl groups to sites that had\nnone (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1016/s0092-8674(00)81656-6",children:"Okano et al., 1999"}),"). TET enzymes\nstart the work of removing marks by converting 5-methylcytosine to\n",(0,d.jsx)(t.strong,{children:"5-hydroxymethylcytosine"})," (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1126/science.1170116",children:"Tahiliani et al.,\n2009"}),")."]}),"\n",(0,d.jsx)(t.h2,{id:"histone-modifications",children:"Histone Modifications"}),"\n",(0,d.jsxs)(t.p,{children:[(0,d.jsx)(t.a,{href:"/docs/biological-foundations/cells-genomes-dna-chromosomes#how-dna-is-packaged",children:"Histones"}),"\nare the proteins DNA wraps around. Each nucleosome is a core of eight histones with 145\nto 147 base pairs of DNA wound around it, and flexible ",(0,d.jsx)(t.strong,{children:"tails"}),", 15 to 36 amino acids\nlong, stick out from it (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1021/cr500373h",children:"McGinty and Tan, 2015"}),").\nEnzymes attach small chemical groups to particular amino acids in these tails, most\noften lysines."]}),"\n",(0,d.jsxs)(t.p,{children:["This page covers two kinds of marks (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/cr.2011.22",children:"Bannister and Kouzarides,\n2011"}),"):"]}),"\n",(0,d.jsxs)(t.ul,{children:["\n",(0,d.jsxs)(t.li,{children:[(0,d.jsx)(t.strong,{children:"Acetylation"})," adds an acetyl group to a lysine. That cancels the lysine's positive\ncharge and can weaken its hold on DNA. Enzymes called histone acetyltransferases add\nthese marks, and histone deacetylases remove them."]}),"\n",(0,d.jsxs)(t.li,{children:[(0,d.jsx)(t.strong,{children:"Methylation"})," adds one, two or three methyl groups to a lysine. The same lysine can\ncarry either kind of mark."]}),"\n"]}),"\n",(0,d.jsxs)(t.p,{children:["Each mark is named with a short code: the histone, then the amino acid and its position\nin the tail, then the mark (",(0,d.jsx)(t.a,{href:"#figure-7-5",children:"Figure 7.5"}),"). H3K27me3 means three methyl\ngroups (me3) on lysine (K) 27 of histone H3, and H3K27ac is an acetyl group on the same\nlysine. Positions are counted without the methionine that starts the protein, because\nthe cell trims it off soon after the protein is made (",(0,d.jsx)(t.a,{href:"https://doi.org/10.3390/ijms25158498",children:"Blasco-Santana et al.,\n2024"}),")."]}),"\n",(0,d.jsxs)(t.figure,{className:"lg-figure lg-figure--themed",id:"figure-7-5",children:[(0,d.jsx)(t.img,{alt:"Two sections. Section 1, reading a mark's name: the first 36 amino acids of the histone H3 tail written as letters, leading into a nucleosome, a ball with DNA wrapped around it and short tails sticking out. Lysines at positions 4, 9, 27 and 36 are bold and numbered, and three methyl groups sit on lysine 27. Below, the name H3K27me3 is split into three parts: H3 means histone H3, K27 means lysine at position 27, and me3 means three methyl groups. Section 2, marks and packing: on the left, nucleosomes packed tightly in a zigzag, with tails carrying methyl groups, labeled H3K9me3, H3K27me3, tightly packed, genes kept off. On the right, three nucleosomes spaced along a stretch of DNA, with tails carrying acetyl groups, labeled H3K27ac, loosely packed, genes active.",src:h().A+"",width:"392",height:"407"}),(0,d.jsx)(t.img,{className:"lg-figure__dark",src:i().A,alt:"Two sections. Section 1, reading a mark's name: the first 36 amino acids of the histone H3 tail written as letters, leading into a nucleosome, a ball with DNA wrapped around it and short tails sticking out. Lysines at positions 4, 9, 27 and 36 are bold and numbered, and three methyl groups sit on lysine 27. Below, the name H3K27me3 is split into three parts: H3 means histone H3, K27 means lysine at position 27, and me3 means three methyl groups. Section 2, marks and packing: on the left, nucleosomes packed tightly in a zigzag, with tails carrying methyl groups, labeled H3K9me3, H3K27me3, tightly packed, genes kept off. On the right, three nucleosomes spaced along a stretch of DNA, with tails carrying acetyl groups, labeled H3K27ac, loosely packed, genes active.",width:"392",height:"407",loading:"lazy",decoding:"async"}),(0,d.jsxs)(t.figcaption,{children:[(0,d.jsx)(t.span,{className:"lg-figure__number",children:"Figure 7.5"})," Histone marks. A mark's name gives the histone, the amino acid and its position in the tail, and the chemical group, so H3K27me3 is three methyl groups on lysine 27 of histone H3. Some marks tend to go with tightly packed DNA where genes are kept off, and others with loosely packed DNA where genes are active, though each has exceptions."]})]}),"\n",(0,d.jsxs)(t.p,{children:["Each mark is associated with a particular kind of region. The Roadmap Epigenomics\nproject mapped the most common ones in 111 human tissues and cell types (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/nature14248",children:"Roadmap\nEpigenomics Consortium, 2015"}),"):"]}),"\n",(0,d.jsxs)(t.table,{children:[(0,d.jsx)(t.thead,{children:(0,d.jsxs)(t.tr,{children:[(0,d.jsx)(t.th,{children:"Mark"}),(0,d.jsx)(t.th,{children:"Usually found at"})]})}),(0,d.jsxs)(t.tbody,{children:[(0,d.jsxs)(t.tr,{children:[(0,d.jsx)(t.td,{children:"H3K4me3"}),(0,d.jsx)(t.td,{children:"Promoters"})]}),(0,d.jsxs)(t.tr,{children:[(0,d.jsx)(t.td,{children:"H3K4me1"}),(0,d.jsx)(t.td,{children:(0,d.jsx)(t.a,{href:"/docs/biological-foundations/transcription#genomic-regions-and-transcription",children:"Enhancers"})})]}),(0,d.jsxs)(t.tr,{children:[(0,d.jsx)(t.td,{children:"H3K27ac"}),(0,d.jsx)(t.td,{children:"Active promoters and enhancers"})]}),(0,d.jsxs)(t.tr,{children:[(0,d.jsx)(t.td,{children:"H3K36me3"}),(0,d.jsx)(t.td,{children:"The bodies of genes being transcribed"})]}),(0,d.jsxs)(t.tr,{children:[(0,d.jsx)(t.td,{children:"H3K27me3"}),(0,d.jsx)(t.td,{children:"Genes switched off by Polycomb proteins, which may be on in other cells"})]}),(0,d.jsxs)(t.tr,{children:[(0,d.jsx)(t.td,{children:"H3K9me3"}),(0,d.jsx)(t.td,{children:"Heterochromatin, especially repeat-rich DNA that is usually packed tight"})]})]})]}),"\n",(0,d.jsxs)(t.p,{children:["H3K27me3 is made by PRC2, a group of Polycomb proteins that helps cells keep their\nidentity (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/nature09784",children:"Margueron and Reinberg, 2011"}),"). It\nusually marks DNA that's packed away in one cell type but may be opened in another,\nwhile H3K9me3 tends to mark DNA that stays packed across many cell types (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1186/1756-8935-8-3",children:"Saksouk et\nal., 2015"}),")."]}),"\n",(0,d.jsxs)(t.p,{children:["These tendencies have exceptions. In embryonic stem cells, many developmental genes\ncarry H3K4me3 and H3K27me3 at once, which keeps them off but ready to switch on later\n(",(0,d.jsx)(t.a,{href:"https://doi.org/10.1016/j.cell.2006.02.041",children:"Bernstein et al., 2006"}),"). A family of\nactive genes that code for zinc finger proteins carries H3K9me3 near their ends\n(",(0,d.jsx)(t.a,{href:"https://doi.org/10.1371/journal.pone.0017121",children:"Blahnik et al., 2011"}),"). And when\nengineered cells lost most of the H3K27ac at their enhancers, their genes' activity\nbarely changed (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1186/s13059-020-01957-w",children:"Zhang et al., 2020"}),"). A\nmark tells you what usually goes on at a region, but it doesn't always cause it."]}),"\n",(0,d.jsxs)(t.p,{children:["Some histone marks can also be passed on when a cell divides, at least those that keep\ngenes off. When DNA is copied, the old histones are shared between the two new copies,\nso each inherits about half the marks, and enzymes that recognize a mark and add more of\nit fill in the rest. For H3K9me3 and H3K27me3, that refilling can take more than one\ncell cycle (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1101/gad.256354.114",children:"Alabert et al., 2015"}),"). In fruit\nflies, H3K27me3 carried a gene's off state through several divisions (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1126/science.aai8236",children:"Coleman and\nStruhl, 2017"}),"), though keeping it going also\nneeded the DNA sequences that call in PRC2 (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1126/science.aai8266",children:"Laprell et al.,\n2017"}),"). Histones from active regions aren't\nkept in place the same way (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1016/j.cell.2019.10.009",children:"Escobar et al.,\n2019"}),"), so whether marks of active genes are\ninherited is less clear."]}),"\n",(0,d.jsx)(t.h2,{id:"measuring-the-marks",children:"Measuring the Marks"}),"\n",(0,d.jsxs)(t.p,{children:["Standard sequencing reads 5-methylcytosine as an ordinary C, and ",(0,d.jsx)(t.a,{href:"/docs/next-generation-sequencing/library-preparation#making-copies",children:"PCR copies lose the\nmarks"}),", so\nmethylation needs its own methods."]}),"\n",(0,d.jsxs)(t.ul,{children:["\n",(0,d.jsxs)(t.li,{children:[(0,d.jsx)(t.strong,{children:"Bisulfite sequencing"})," treats DNA with sodium bisulfite, which turns unmethylated\ncytosine into uracil but leaves 5-methylcytosine alone. PCR then copies each uracil as\nT (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1073/pnas.89.5.1827",children:"Frommer et al., 1992"}),"). After alignment, a\nC that stayed C was methylated, and a C that became T wasn't. Run across a whole\ngenome, it maps methylation at nearly every C. One such study found that 99.98% of the\nmethylation in a fibroblast cell line was at CpG sites, while in embryonic stem cells\nnearly a quarter was elsewhere (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/nature08514",children:"Lister et al.,\n2009"}),"). Bisulfite can't tell 5-methylcytosine\nfrom 5-hydroxymethylcytosine, because neither one becomes uracil, so both are read as\nC (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1371/journal.pone.0008888",children:"Huang et al., 2010"}),")."]}),"\n",(0,d.jsxs)(t.li,{children:[(0,d.jsx)(t.strong,{children:"Enzymatic methyl-seq (EM-seq)"})," makes the same distinction with enzymes in place of\nbisulfite, which damages and breaks DNA. Because it's gentler, it works with as little\nas 100 picograms of DNA (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1101/gr.266551.120",children:"Vaisvila et al.,\n2021"}),"). Like bisulfite, it reads both modified\nforms as C."]}),"\n",(0,d.jsxs)(t.li,{children:[(0,d.jsx)(t.strong,{children:(0,d.jsx)(t.a,{href:"/docs/next-generation-sequencing/long-read-sequencing",children:"Long reads"})})," come\nfrom the original molecule, so methylation changes the signal itself and can be\ndetected without any conversion."]}),"\n"]}),"\n",(0,d.jsxs)(t.p,{children:["Histone marks are measured through the DNA they're attached to.\n",(0,d.jsx)(t.a,{href:"/docs/next-generation-sequencing/types-of-sequencing/chip-seq",children:"ChIP-seq"})," uses\nan antibody against one mark, such as H3K27me3, to pull out the DNA wrapped around\nnucleosomes carrying it.\n",(0,d.jsx)(t.a,{href:"/docs/next-generation-sequencing/types-of-sequencing/atac-seq",children:"ATAC-seq"})," shows\nwhich stretches of DNA are open enough for an enzyme to reach, though it can't say which\nmarks are present."]}),"\n",(0,d.jsx)(t.h2,{id:"epigenetics-in-cancer",children:"Epigenetics in Cancer"}),"\n",(0,d.jsx)(t.h3,{id:"too-little-and-too-much-methylation",children:"Too Little and Too Much Methylation"}),"\n",(0,d.jsxs)(t.p,{children:["In 1983, two labs independently reported that cancer cells carry less DNA methylation\nthan normal cells. One looked at specific genes (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/301089a0",children:"Feinberg and Vogelstein,\n1983"}),"), and the other measured total 5-methylcytosine\nin 103 tumors (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1093/nar/11.19.6883",children:"Gama-Sosa et al., 1983"}),"). At the\nsame time, CpG islands at the promoters of some tumor suppressor genes gain methylation,\nwhich can silence those genes without any change to their sequence. Genes silenced this\nway include CDKN2A (p16), VHL, APC and MLH1 (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1101/cshperspect.a019505",children:"Baylin and Jones,\n2016"}),")."]}),"\n",(0,d.jsxs)(t.p,{children:["MLH1 is a mismatch repair gene, and losing it causes ",(0,d.jsx)(t.a,{href:"/docs/genomic-variation/insertions-and-deletions#where-indels-happen",children:"microsatellite\ninstability"}),"\n(MSI). In colorectal cancers that aren't inherited, MSI usually traces back to\nmethylation. One study found a heavily methylated MLH1 promoter in 11 of 13 tumors with\nMSI and in only 2 of 21 tumors without it. In cell lines, removing the methylation\nswitched MLH1 back on and restored mismatch repair (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1073/pnas.95.12.6870",children:"Herman et al.,\n1998"}),")."]}),"\n",(0,d.jsx)(t.h3,{id:"mutations-in-the-machinery",children:"Mutations in the Machinery"}),"\n",(0,d.jsxs)(t.p,{children:["Some childhood cancers show how directly the epigenome can drive cancer. In diffuse\nintrinsic pontine glioma (DIPG), a brainstem tumor of children, 78% of tumors carry a\nmutation in a histone H3 gene that swaps lysine 27 for methionine, called K27M (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/ng.1102",children:"Wu et\nal., 2012"}),"). An independent study published the same\nyear found mutations at lysine 27 or glycine 34 of histone H3.3 in 31% of pediatric\nglioblastomas, the first time recurrent mutations in a human histone had been reported\n(",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/nature10833",children:"Schwartzentruber et al., 2012"}),"). The K27M histone\nblocks PRC2, so tumors carrying it have greatly reduced H3K27me3 (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1126/science.1232245",children:"Lewis et al.,\n2013"}),"). The World Health Organization now\ngroups these tumors as diffuse midline glioma, H3 K27-altered, a category that also\ncovers tumors that lose H3K27me3 in other ways (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1093/neuonc/noab106",children:"Louis et al.,\n2021"}),"). Newer papers write the same mutation as\nK28M, because they count the first methionine."]}),"\n",(0,d.jsx)(t.p,{children:"Other cancers disrupt the enzymes that write or erase marks:"}),"\n",(0,d.jsxs)(t.ul,{children:["\n",(0,d.jsxs)(t.li,{children:[(0,d.jsx)(t.strong,{children:"IDH mutations."})," Mutant IDH1 makes a molecule called 2-hydroxyglutarate (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/nature08617",children:"Dang et\nal., 2009"}),"), which blocks TET enzymes and other\nenzymes that remove marks (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1016/j.ccr.2010.12.014",children:"Xu et al.,\n2011"}),"). Leukemias with IDH mutations carry\nextra methylation across the genome (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1016/j.ccr.2010.11.015",children:"Figueroa et al.,\n2010"}),"), and adding mutant IDH1 to cultured\nbrain cells was enough to give them the heavy CpG island methylation seen in\nIDH-mutant gliomas (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/nature10866",children:"Turcan et al., 2012"}),"). In\nchildren with malignant gliomas, one study found IDH1 mutations only in patients aged\n14 or older (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1007/s00381-010-1264-1",children:"Pollack et al., 2011"}),")."]}),"\n",(0,d.jsxs)(t.li,{children:[(0,d.jsx)(t.strong,{children:"Rhabdoid tumors"}),", including atypical teratoid/rhabdoid tumors (ATRT) of the brain,\ncarry very few mutations, about 0.19 per million bases on average. Loss of SMARCB1,\npart of a protein complex that remodels chromatin, is essentially the only one they\nshare (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1172/JCI64400",children:"Lee et al., 2012"}),")."]}),"\n",(0,d.jsxs)(t.li,{children:[(0,d.jsx)(t.strong,{children:"Ependymomas"})," of the hindbrain showed no significant recurrent single-base mutations\nwhen 47 tumors were sequenced, yet the group with the worst outcomes showed heavy CpG\nisland methylation (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/nature13108",children:"Mack et al., 2014"}),")."]}),"\n"]}),"\n",(0,d.jsxs)(t.p,{children:["Methylation patterns are distinctive enough to identify a tumor type. A classifier built\nfrom methylation profiles of 2,801 reference samples, covering 82 kinds of brain tumor\nplus normal tissue, matched 88% of 1,104 new cases to a class, and it changed the\noriginal diagnosis in 129 of them, about 12% (",(0,d.jsx)(t.a,{href:"https://doi.org/10.1038/nature26000",children:"Capper et al.,\n2018"}),")."]})]})}function f(e={}){const{wrapper:t}={...(0,c.R)(),...e.components};return t?(0,d.jsx)(t,{...e,children:(0,d.jsx)(y,{...e})}):y(e)}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var s=n(6540);const a={},i=s.createContext(a);function o(e){const t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);